CREATE OR REPLACE FUNCTION public.archive_enrich_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  rawu text := upper(coalesce(new.normalized_text, new.raw_text, ''));
  n numeric;
  m text[];
  w numeric;
  g numeric;
  c integer;
  min_vis integer := null;
  min_ceiling integer := null;
  has_explicit_weather boolean := false;
begin
  n := public.archive_try_numeric(new.payload->>'visibility_m');
  if n is not null then min_vis := round(n)::integer; end if;
  if min_vis is null and rawu ~ '(^|[[:space:]])CAVOK([[:space:]=]|$)' then min_vis := 10000; end if;
  if min_vis is null then
    for m in select regexp_matches(rawu, '(^|[[:space:]])([0-9]{4})([[:space:]=]|$)', 'g') loop
      begin
        c := m[2]::integer;
        if c between 0 and 9999 and (min_vis is null or c < min_vis) then min_vis := c; end if;
      exception when others then null;
      end;
    end loop;
  end if;
  new.visibility_m := min_vis;

  n := public.archive_try_numeric(new.payload->>'wind_direction_deg');
  if n is not null then new.wind_direction_deg := mod(round(n)::integer,360)::smallint; if round(n)::integer = 360 then new.wind_direction_deg := 360; end if; else new.wind_direction_deg := null; end if;

  n := public.archive_try_numeric(new.payload->>'wind_speed_kt');
  if n is null then n := public.archive_try_numeric(new.payload->>'wind_speed_ms'); if n is not null then n := n * 1.9438444924406; end if; end if;
  new.wind_speed_kt := case when n is null then null else round(n,2) end;

  n := public.archive_try_numeric(new.payload->>'wind_gust_kt');
  if n is null then n := public.archive_try_numeric(new.payload->>'wind_gust_ms'); if n is not null then n := n * 1.9438444924406; end if; end if;
  new.gust_kt := case when n is null then null else round(n,2) end;

  for m in select regexp_matches(rawu, '([0-9]{3}|VRB)([0-9]{2,3})(G([0-9]{2,3}))?KT', 'g') loop
    begin
      w := m[2]::numeric;
      g := case when m[4] is null then null else m[4]::numeric end;
      if new.wind_speed_kt is null or w > new.wind_speed_kt then new.wind_speed_kt := w; end if;
      if g is not null and (new.gust_kt is null or g > new.gust_kt) then new.gust_kt := g; end if;
      if new.wind_direction_deg is null and m[1] <> 'VRB' then new.wind_direction_deg := m[1]::smallint; end if;
    exception when others then null;
    end;
  end loop;

  n := public.archive_try_numeric(new.payload->>'temperature_c');
  new.temperature_c := case when n is null then null else round(n,2) end;
  n := public.archive_try_numeric(new.payload->>'pressure_hpa');
  if n is null then
    m := regexp_match(rawu, 'Q([0-9]{4})');
    if m is not null then n := public.archive_try_numeric(m[1]); end if;
  end if;
  new.qnh_hpa := case when n is null then null else round(n,2) end;

  n := public.archive_try_numeric(new.payload->>'ceiling_ft_agl');
  if n is null then n := public.archive_try_numeric(new.payload->>'ceiling_m_agl'); if n is not null then n := n * 3.2808398950131; end if; end if;
  if n is not null then min_ceiling := round(n)::integer; end if;
  for m in select regexp_matches(rawu, '(BKN|OVC)([0-9]{3})', 'g') loop
    begin c := m[2]::integer * 100; if min_ceiling is null or c < min_ceiling then min_ceiling := c; end if; exception when others then null; end;
  end loop;
  for m in select regexp_matches(rawu, 'VV([0-9]{3})', 'g') loop
    begin c := m[1]::integer * 100; if min_ceiling is null or c < min_ceiling then min_ceiling := c; end if; exception when others then null; end;
  end loop;
  new.ceiling_ft := min_ceiling;

  new.has_fg := rawu ~ '(^|[[:space:]])[-+]?(FZ)?FG([[:space:]=]|$)';
  new.has_br := rawu ~ '(^|[[:space:]])[-+]?BR([[:space:]=]|$)';
  new.has_mifg := rawu ~ '(^|[[:space:]])[-+]?MIFG([[:space:]=]|$)';
  new.has_ts := rawu ~ '(^|[[:space:]])[-+]?(VC)?TS[A-Z]*([[:space:]=]|$)';
  new.has_ra := rawu ~ '(^|[[:space:]])[-+]?[A-Z]*RA[A-Z]*([[:space:]=]|$)';
  new.has_sn := rawu ~ '(^|[[:space:]])[-+]?[A-Z]*SN[A-Z]*([[:space:]=]|$)';
  new.has_cb := rawu ~ '(FEW|SCT|BKN|OVC)[0-9]{3}CB([[:space:]=]|$)' or rawu ~ '(^|[[:space:]])CB([[:space:]=]|$)';
  new.has_tcu := rawu ~ '(FEW|SCT|BKN|OVC)[0-9]{3}TCU([[:space:]=]|$)' or rawu ~ '(^|[[:space:]])TCU([[:space:]=]|$)';
  new.has_vv := rawu ~ '(^|[[:space:]])VV([0-9]{3}|///)([[:space:]=]|$)';

  has_explicit_weather := rawu ~ '(^|[[:space:]])[-+]?(VC)?(MI|PR|BC|DR|BL|SH|TS|FZ)?(DZ|RA|SN|SG|IC|PL|GR|GS|UP|BR|FG|FU|VA|DU|SA|HZ|PO|SQ|FC|SS|DS)([A-Z]{0,4})?([[:space:]=]|$)';
  if new.message_type = 'METAR' and new.visibility_m is not null and new.visibility_m < 1000 and not has_explicit_weather then
    new.has_fg := true;
  end if;

  new.weather_codes := '{}'::text[];
  if new.has_fg then new.weather_codes := array_append(new.weather_codes,'FG'); end if;
  if new.has_br then new.weather_codes := array_append(new.weather_codes,'BR'); end if;
  if new.has_mifg then new.weather_codes := array_append(new.weather_codes,'MIFG'); end if;
  if new.has_ts then new.weather_codes := array_append(new.weather_codes,'TS'); end if;
  if new.has_ra then new.weather_codes := array_append(new.weather_codes,'RA'); end if;
  if new.has_sn then new.weather_codes := array_append(new.weather_codes,'SN'); end if;
  if new.has_cb then new.weather_codes := array_append(new.weather_codes,'CB'); end if;
  if new.has_tcu then new.weather_codes := array_append(new.weather_codes,'TCU'); end if;
  if new.has_vv then new.weather_codes := array_append(new.weather_codes,'VV'); end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.archive_try_numeric(v text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if v is null or btrim(v) = '' then return null; end if;
  return v::numeric;
exception when others then
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.run_message_archive_retention()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_quota_bytes constant bigint := 524288000; -- 500 MiB
  v_db_bytes bigint;
  v_usage numeric(7,3);
  v_mode text := 'none';
  v_keep_days integer := null;
  v_batch integer := null;
  v_cutoff timestamptz := null;
  v_eligible integer := 0;
  v_deleted integer := 0;
  v_note text;
begin
  -- Prevent overlapping retention runs.
  perform pg_advisory_xact_lock(640219026, 1);

  v_db_bytes := pg_database_size(current_database());
  v_usage := round((v_db_bytes::numeric * 100.0) / v_quota_bytes::numeric, 3);

  if v_usage < 75 then
    v_note := 'Below 75% threshold; no deletion.';
  else
    if v_usage >= 85 then
      v_mode := 'emergency';
      v_keep_days := 30;
      v_batch := 5000;
    else
      v_mode := 'normal';
      v_keep_days := 90;
      v_batch := 1000;
    end if;

    v_cutoff := now() - make_interval(days => v_keep_days);

    select count(*)::integer
      into v_eligible
    from public.messages m
    join public.message_retention_alt_stations s
      on s.station_code = m.station_code
     and s.enabled
    where m.archive_time < v_cutoff
      and m.station_code not in ('EPIR', '12342');

    if v_eligible > 0 then
      with doomed as (
        select m.id
        from public.messages m
        join public.message_retention_alt_stations s
          on s.station_code = m.station_code
         and s.enabled
        where m.archive_time < v_cutoff
          and m.station_code not in ('EPIR', '12342')
        order by m.archive_time asc, m.id asc
        limit v_batch
      ), deleted as (
        delete from public.messages m
        using doomed d
        where m.id = d.id
        returning 1
      )
      select count(*)::integer into v_deleted from deleted;

      v_note := format(
        'Deleted oldest alternate-airport rows only. Protected stations EPIR and 12342 are never eligible. Minimum retained history: %s days.',
        v_keep_days
      );
    else
      v_note := format(
        'Threshold reached but no alternate-airport rows older than %s days are eligible. Protected stations untouched.',
        v_keep_days
      );
    end if;
  end if;

  insert into public.message_retention_log (
    database_bytes_before, quota_bytes, usage_percent, mode,
    keep_days, batch_limit, eligible_rows, deleted_rows, cutoff, note
  ) values (
    v_db_bytes, v_quota_bytes, v_usage, v_mode,
    v_keep_days, v_batch, v_eligible, v_deleted, v_cutoff, v_note
  );

  return jsonb_build_object(
    'ok', true,
    'database_bytes', v_db_bytes,
    'quota_bytes', v_quota_bytes,
    'usage_percent', v_usage,
    'mode', v_mode,
    'keep_days', v_keep_days,
    'batch_limit', v_batch,
    'eligible_rows', v_eligible,
    'deleted_rows', v_deleted,
    'cutoff', v_cutoff,
    'note', v_note
  );
end;
$function$
